function(container, apiUrl, tables) {
  let selectedProducts = [];
  let allProducts = [];
  let stores = [];
  let predictions = [];
  let salesData = [];

  // 再描画関数の定義
  function renderProducts(products) {
    const tbody = container.querySelector("#products-tbody");
    tbody.innerHTML = products.map(product => {
      const prediction = predictions.find(p => p.商品ID === product.商品ID) || {};
      const predictedQty = prediction.予測数量 || 0;

      return `
        <tr data-id="${product.商品ID}">
          <td><input type="checkbox" class="product-checkbox" data-product-id="${product.商品ID}"></td>
          <td>${product.商品コード || ""}</td>
          <td>${product.商品名 || ""}</td>
          <td>¥${(product.単価 || 0).toLocaleString()}</td>
          <td>
            ${predictedQty}
            ${predictedQty > 0 ? `<button class="prediction-btn" data-product-id="${product.商品ID}">根拠</button>` : ""}
          </td>
          <td><input type="number" class="input quantity-input" min="0" value="${predictedQty}" data-product-id="${product.商品ID}"></td>
          <td><button class="action-btn secondary add-to-order-btn" data-product-id="${product.商品ID}">追加</button></td>
        </tr>
      `;
    }).join("");
  }

  function renderOrderItems() {
    const tbody = container.querySelector("#order-items-tbody");
    tbody.innerHTML = selectedProducts.map(item => {
      const subtotal = (item.単価 || 0) * (item.発注数量 || 0);
      const prediction = predictions.find(p => p.商品ID === item.商品ID) || {};

      return `
        <tr data-id="${item.商品ID}">
          <td>${item.商品コード || ""}</td>
          <td>${item.商品名 || ""}</td>
          <td>¥${(item.単価 || 0).toLocaleString()}</td>
          <td>${prediction.予測数量 || 0}</td>
          <td><input type="number" class="input quantity-input order-quantity-input" min="0" value="${item.発注数量 || 0}" data-product-id="${item.商品ID}"></td>
          <td>¥${subtotal.toLocaleString()}</td>
          <td><button class="action-btn secondary remove-from-order-btn" data-product-id="${item.商品ID}">削除</button></td>
        </tr>
      `;
    }).join("");

    updateTotalAmount();
  }

  function updateTotalAmount() {
    const total = selectedProducts.reduce((sum, item) => {
      return sum + ((item.単価 || 0) * (item.発注数量 || 0));
    }, 0);
    container.querySelector("#total-amount").textContent = `¥${total.toLocaleString()}`;
  }

  function showError(message) {
    alert(message);
  }

  function validateForm() {
    const storeId = container.querySelector("#store-select").value;
    const orderDate = container.querySelector("#order-date").value;
    const deliveryDate = container.querySelector("#delivery-date").value;

    if (!storeId) {
      showError("店舗を選択してください");
      return false;
    }

    if (!orderDate) {
      showError("発注日付を入力してください");
      return false;
    }

    if (!deliveryDate) {
      showError("納期を指定してください");
      return false;
    }

    if (new Date(deliveryDate) <= new Date(orderDate)) {
      showError("納期は発注日より後の日付を指定してください");
      return false;
    }

    if (selectedProducts.length === 0) {
      showError("発注する商品を選択してください");
      return false;
    }

    for (const product of selectedProducts) {
      if (!product.発注数量 || product.発注数量 <= 0) {
        showError(`${product.商品名}の発注数量は1以上で入力してください`);
        return false;
      }
    }

    return true;
  }

  // 初期データの読み込み
  async function loadInitialData() {
    try {
      // 店舗データの読み込み
      const storeData = await window.aivicApi.list(1);
      if (storeData) {
        stores = storeData.filter(s => s.有効フラグ);
        const storeSelect = container.querySelector("#store-select");
        storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
          stores.map(store => `<option value="${store.店舗ID}">${store.店舗名}</option>`).join("");
      }

      // 商品データの読み込み
      const productData = await window.aivicApi.list(2);
      if (productData) {
        allProducts = productData.filter(p => p.有効フラグ);
        renderProducts(allProducts);
      }

      // 需要予測データの読み込み
      const predictionData = await window.aivicApi.list(8);
      if (predictionData) {
        predictions = predictionData;
      }

      // 売上実績データの読み込み
      const salesDataResult = await window.aivicApi.list(3);
      if (salesDataResult) {
        salesData = salesDataResult;
      }
    } catch (error) {
      console.error("データ読み込みエラー:", error);
    }
  }

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector("#order-date").value = today;

  // 商品検索
  container.querySelector("#btn-search-products").addEventListener("click", () => {
    const category = container.querySelector("#category-select").value;
    const searchTerm = container.querySelector("#product-search").value.toLowerCase();

    let filteredProducts = allProducts;

    if (category) {
      // カテゴリでフィルタ（簡易実装）
      filteredProducts = filteredProducts.filter(p => 
        p.商品名 && p.商品名.includes(category)
      );
    }

    if (searchTerm) {
      filteredProducts = filteredProducts.filter(p => 
        (p.商品名 && p.商品名.toLowerCase().includes(searchTerm)) ||
        (p.商品コード && p.商品コード.toLowerCase().includes(searchTerm))
      );
    }

    if (filteredProducts.length === 0 && searchTerm) {
      showError("該当する商品が見つかりません");
    }

    renderProducts(filteredProducts);
  });

  // 商品を発注リストに追加
  container.addEventListener("click", (e) => {
    const addBtn = e.target.closest(".add-to-order-btn");
    if (addBtn) {
      const productId = addBtn.dataset.productId;
      const product = allProducts.find(p => p.商品ID === productId);
      const quantityInput = container.querySelector(`input[data-product-id="${productId}"]`);
      const quantity = parseInt(quantityInput.value) || 0;

      if (quantity <= 0) {
        showError("発注数量は1以上で入力してください");
        return;
      }

      if (isNaN(quantity)) {
        showError("発注数量は数値で入力してください");
        return;
      }

      // 既に追加済みかチェック
      const existingIndex = selectedProducts.findIndex(p => p.商品ID === productId);
      if (existingIndex >= 0) {
        selectedProducts[existingIndex].発注数量 = quantity;
      } else {
        selectedProducts.push({
          ...product,
          発注数量: quantity
        });
      }

      renderOrderItems();
    }

    // 発注リストから削除
    const removeBtn = e.target.closest(".remove-from-order-btn");
    if (removeBtn) {
      const productId = removeBtn.dataset.productId;
      selectedProducts = selectedProducts.filter(p => p.商品ID !== productId);
      renderOrderItems();
    }

    // 予測根拠表示
    const predictionBtn = e.target.closest(".prediction-btn");
    if (predictionBtn) {
      const productId = predictionBtn.dataset.productId;
      showPredictionDetails(productId);
    }

    // モーダル閉じる
    const closeBtn = e.target.closest(".close-btn");
    if (closeBtn) {
      container.querySelectorAll(".modal").forEach(modal => modal.classList.add("hidden"));
    }
  });

  // 発注数量の変更
  container.addEventListener("input", (e) => {
    if (e.target.classList.contains("order-quantity-input")) {
      const productId = e.target.dataset.productId;
      const quantity = parseInt(e.target.value) || 0;

      const product = selectedProducts.find(p => p.商品ID === productId);
      if (product) {
        product.発注数量 = quantity;
        updateTotalAmount();
      }
    }
  });

  // 在庫状況確認
  container.querySelector("#btn-check-stock").addEventListener("click", () => {
    showStockDetails();
  });

  // 過去実績参照
  container.querySelector("#btn-check-history").addEventListener("click", () => {
    showHistoryDetails();
  });

  // 発注総額表示
  container.querySelector("#btn-calculate-total").addEventListener("click", () => {
    updateTotalAmount();
    alert(`発注総額: ${container.querySelector("#total-amount").textContent}`);
  });

  // 発注書作成
  container.querySelector("#btn-create-order").addEventListener("click", async () => {
    if (!validateForm()) {
      return;
    }

    const storeId = container.querySelector("#store-select").value;
    const orderDate = container.querySelector("#order-date").value;
    const deliveryDate = container.querySelector("#delivery-date").value;

    try {
      // 各商品の発注データを保存
      for (const product of selectedProducts) {
        const orderData = {
          店舗ID: storeId,
          商品ID: product.商品ID,
          発注日: new Date(orderDate).toISOString(),
          納期予定日: new Date(deliveryDate).toISOString(),
          発注数量: product.発注数量,
          発注単価: product.単価,
          発注金額: product.単価 * product.発注数量,
          発注方法: "手動発注",
          発注ステータス: "発注済",
          仕入先ID: product.仕入先ID || "default-supplier",
          発注理由: "発注書作成画面からの手動発注",
          自動発注フラグ: false,
          作成者ID: "current-user",
          更新者ID: "current-user"
        };

        await window.aivicApi.save(9, orderData);
      }

      alert("発注書が正常に作成されました");
      window.showScreen('scr-1778591852463');
    } catch (error) {
      console.error("発注書作成エラー:", error);
      showError("発注書の作成に失敗しました");
    }
  });

  function showPredictionDetails(productId) {
    const product = allProducts.find(p => p.商品ID === productId);
    const prediction = predictions.find(p => p.商品ID === productId);

    if (!prediction) {
      showError("予測データが見つかりません");
      return;
    }

    const modal = container.querySelector("#prediction-modal");
    const details = container.querySelector("#prediction-details");

    details.innerHTML = `
      <div class="prediction-item">
        <h4>${product.商品名}</h4>
        <p><strong>予測数量:</strong> ${prediction.予測数量 || 0}個</p>
        <p><strong>予測精度:</strong> ${prediction.予測精度 || 0}%</p>
        <p><strong>推奨発注数量:</strong> ${prediction.推奨発注数量 || 0}個</p>
        <p><strong>予測モデル:</strong> ${prediction.予測モデルバージョン || "不明"}</p>
        <p><strong>予測ステータス:</strong> ${prediction.予測ステータス || "不明"}</p>
        <p><strong>備考:</strong> ${prediction.備考 || "なし"}</p>
      </div>
    `;

    modal.classList.remove("hidden");
  }

  function showStockDetails() {
    const modal = container.querySelector("#stock-modal");
    const details = container.querySelector("#stock-details");

    details.innerHTML = selectedProducts.map(product => `
      <div class="stock-item">
        <h4>${product.商品名}</h4>
        <p><strong>商品コード:</strong> ${product.商品コード}</p>
        <p><strong>発注数量:</strong> ${product.発注数量}個</p>
        <p><strong>単価:</strong> ¥${product.単価.toLocaleString()}</p>
        <p><strong>小計:</strong> ¥${(product.単価 * product.発注数量).toLocaleString()}</p>
        <p><strong>リードタイム:</strong> ${product.リードタイム日数 || 0}日</p>
        <p><strong>最小発注数量:</strong> ${product.最小発注数量 || 0}個</p>
      </div>
    `).join("");

    modal.classList.remove("hidden");
  }

  function showHistoryDetails() {
    const modal = container.querySelector("#history-modal");
    const details = container.querySelector("#history-details");

    // 過去3ヶ月の売上実績を表示（簡易実装）
    const threeMonthsAgo = new Date();
    threeMonthsAgo.setMonth(threeMonthsAgo.getMonth() - 3);

    details.innerHTML = selectedProducts.map(product => {
      const productSales = salesData.filter(s => 
        s.商品ID === product.商品ID && 
        new Date(s.売上日) >= threeMonthsAgo
      );

      const totalSales = productSales.reduce((sum, s) => sum + (s.販売数量 || 0), 0);
      const avgMonthlySales = Math.round(totalSales / 3);

      return `
        <div class="history-item">
          <h4>${product.商品名}</h4>
          <p><strong>過去3ヶ月売上合計:</strong> ${totalSales}個</p>
          <p><strong>月平均売上:</strong> ${avgMonthlySales}個</p>
          <p><strong>現在の発注数量:</strong> ${product.発注数量}個</p>
          <p><strong>実績データ件数:</strong> ${productSales.length}件</p>
        </div>
      `;
    }).join("");

    modal.classList.remove("hidden");
  }

  // モーダル外クリックで閉じる
  container.addEventListener("click", (e) => {
    if (e.target.classList.contains("modal")) {
      e.target.classList.add("hidden");
    }
  });

  // 初期データ読み込み
  loadInitialData();
}
